mapper.select:
select ers.id, ers.student_name, ers.score , ers.exam_id , ppr.name paper_name, ppr.total_score paper_total_score, ers.start_time, ers.end_time, TIMESTAMPDIFF(MINUTE, ers.start_time, ers.end_time) duration from exam_records ers join paper ppr on ers.exam_id = ppr.id where ers.`status` = '已批阅' and ers.is_deleted = 0 and ppr.is_deleted = 0
and ppr.id = #{paperId}
order by ers.score desc , duration asc
limit #{limit};
